package setupui

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up One Workspace</title><link rel="icon" type="image/svg+xml" href="/branding/icons/one_workspace.svg"><style>
:root{font-family:Inter,system-ui,sans-serif;color:#17233b;background:#f4f6fc}*{box-sizing:border-box}body{margin:0}main{max-width:1000px;margin:45px auto;background:white;border:1px solid #e2e7f2;border-radius:25px;overflow:hidden;box-shadow:0 20px 70px #2339760a}header{padding:28px 36px;border-bottom:1px solid #e8ecf5;display:flex;gap:14px;align-items:center}.logo{display:block;width:48px;height:48px;flex:none}.layout{display:grid;grid-template-columns:215px 1fr}aside{background:#f9faff;padding:34px 25px}aside p{color:#7a879e;padding:8px;border-radius:10px;font-size:14px}aside .active{background:#e8eeff;color:#345de5;font-weight:600}article{padding:30px 38px;min-height:530px}h1{font-size:29px;letter-spacing:-.7px;margin:0 0 10px}p{color:#69768d;line-height:1.65}label{display:block;font-size:14px;font-weight:600;margin:18px 0 7px}input,select{width:100%;padding:12px 14px;border:1px solid #ced6e7;border-radius:10px;background:white;color:#17233b;font:inherit}input:focus,select:focus{outline:2px solid #cfdaff;border-color:#345de5}.row{display:flex;gap:9px;align-items:center}.row input{min-width:0}.row button{padding:12px;font-size:14px}.split{display:grid;grid-template-columns:1fr 1fr;gap:15px}button{border:0;border-radius:10px;padding:13px 23px;font:inherit;cursor:pointer;color:white;background:#345de5}button.secondary{background:#eef2fa;color:#32405d}button:disabled{opacity:.45;cursor:wait}nav{display:flex;justify-content:space-between;margin-top:28px}.check{display:flex;align-items:flex-start;gap:10px;font-weight:400;line-height:1.5}.check input{width:18px;margin-top:3px}.note{background:#f1f5ff;padding:15px;border-radius:12px;font-size:14px}small{color:#69768d;display:block;line-height:1.5;margin-top:5px}.error{color:#a42636;background:#fff1f1;padding:14px;border-radius:12px;white-space:pre-wrap;overflow-wrap:anywhere}.progress{height:8px;border-radius:10px;background:#eaf0fc;overflow:hidden;margin:28px 0}.progress b{display:block;width:40%;height:100%;background:#345de5;animation:slide 1.4s ease-in-out infinite}@keyframes slide{50%{transform:translateX(150%)}}section[hidden],div[hidden]{display:none}a{color:#345de5}footer{padding:20px 36px;border-top:1px solid #edf0f6;font-size:12px;color:#7a879e}@media(max-width:720px){main{margin:12px}.layout{display:block}aside{display:none}article{padding:25px}.split{grid-template-columns:1fr}}
</style></head><body><main><header><img class="logo" src="/branding/icons/one_workspace.svg" alt="" width="48" height="48"><b>One Workspace</b><span style="margin-left:auto;color:#8490a5;font-size:13px" id="version">Setup</span></header><div class="layout"><aside><b>Make it yours</b><p id="step0" class="active">1 &nbsp; Your account</p><p id="step1">2 &nbsp; Apps & folders</p><p id="step2">3 &nbsp; Connection</p><p id="step3">4 &nbsp; Install</p></aside><article>
<section id="s0"><h1>Your workspace starts here.</h1><p>One account for your Workspace apps. You can add more people and apps after setup.</p><label for="name">Your name</label><input id="name" autocomplete="name"><label for="email">Account email</label><input id="email" type="email" autocomplete="email"><small>This identifies your account. No email sending service is required.</small><div class="split"><div><label for="password">Password</label><input id="password" type="password" autocomplete="new-password" minlength="12"></div><div><label for="confirm">Confirm password</label><input id="confirm" type="password" autocomplete="new-password"></div></div><small>Use at least 12 characters. Your administrator can reset passwords without email.</small></section>
<section id="s1" hidden><h1>Your apps. Your storage.</h1><p>MyAccounts, Drive and the Docs editor are included. Choose where the suite and your files live.</p><label>Program folder</label><div class="row"><input id="programs" placeholder="I:\OneWorkspace"><button class="secondary" type="button" onclick="browse('programs')">Browse</button></div><small>Choose a new, empty folder. Large app files can use any local drive.</small><label>Private data folder</label><div class="row"><input id="data" placeholder="F:\OneWorkspace-Data"><button class="secondary" type="button" onclick="browse('data')">Browse</button></div><small>Choose a new folder on an NTFS volume. Accounts, secrets and app settings are protected here.</small><label>Your files folder</label><div class="row"><input id="files" placeholder="I:\WorkspaceFiles"><button class="secondary" type="button" onclick="browse('files')">Browse</button></div><small>Existing files stay in place. Documents, Photos and Music folders will be added if absent.</small><label class="check"><input id="photos" type="checkbox" checked> Include the standalone Photos app</label><label class="check"><input id="autostart" type="checkbox"> Start the suite when I sign in to Windows</label></section>
<section id="s2" hidden><h1>Choose how you connect.</h1><p>Start locally, or use your own HTTPS domains. Cloudflare tunnelling is optional.</p><label>Connection</label><select id="mode" onchange="connection()"><option value="local">Local — this computer</option><option value="manual">Existing HTTPS reverse proxy / tunnel</option><option value="cloudflare">Create a dedicated Cloudflare Tunnel</option></select><label>Base port</label><input id="port" type="number" min="1024" max="65530" value="8990"><small>Workspace uses this port and nearby loopback ports for its apps.</small><div id="public" hidden><label>Workspace address</label><input id="origin" placeholder="https://workspace.example.com"><label>MyAccounts address</label><input id="issuer" placeholder="https://login.example.com"><small>Use two unused hostnames. They become stable login addresses; changing them later requires updating OIDC registrations.</small></div><div id="cloudflare" hidden><label>Account ID</label><input id="accountId"><label>Zone ID</label><input id="zoneId"><label>Scoped Cloudflare API token</label><input id="cfToken" type="password" autocomplete="off"><small>Needs Account Cloudflare Tunnel:Edit, Zone DNS:Edit and Zone:Read for the selected account/zone. The API token is used for setup only; the connector token is encrypted locally.</small><label class="check"><input id="authorize" type="checkbox"> Create one dedicated tunnel and two new DNS records in this zone. Do not replace existing records.</label></div><p class="note">Email sending stays off. Accounts work immediately; an administrator can connect an email service later in MyAccounts.</p></section>
<section id="s3" hidden><h1 id="installTitle">Ready for your workspace.</h1><p id="summary">Setup will verify the bundled apps, create your owner account and connect the suite. Current versions of Drive, Docs and Photos are evaluation builds.</p><div class="progress" id="progress" hidden><b></b></div><p id="phase"></p><div id="complete" hidden><p class="note">Installed successfully. Launch Workspace, then open your workspace address once the apps have started. A first start may take a minute.</p><button onclick="launch()" id="launch">Launch Workspace</button><p><a id="workspaceLink" target="_blank" rel="noopener">Open Workspace →</a></p><small>You can close this setup window after launch. Double-click Workspace.exe in your program folder to start the suite again.</small></div></section>
<p id="error" class="error" hidden></p><nav id="navigation"><button class="secondary" onclick="show(step-1)" id="back" disabled>Back</button><button onclick="next()" id="next">Continue →</button></nav></article></div><footer>Self-hosted · No SMTP needed · Your files stay on your chosen drive · Windows x64 evaluation</footer></main>
<script>
let step=0,busy=false,installed=false;const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const $=id=>document.getElementById(id);
async function api(path,body){let r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'X-Setup-Token':token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error(await r.text());return r.status===202||r.status===204?{}:r.json()}
function error(e){$('error').textContent=e.message||e;$('error').hidden=false}
function show(n){if(n<0||n>3||busy)return;step=n;for(let i=0;i<4;i++){$('s'+i).hidden=i!==n;$('step'+i).className=i===n?'active':''}$('back').disabled=n===0;$('next').textContent=n===3?'Install Workspace':'Continue →';$('error').hidden=true}
function request(){let v={};for(let k of ['programs','data','files','name','email','password','confirm','mode','origin','issuer','cfToken','accountId','zoneId'])v[k]=$(k).value.trim();v.password=$('password').value;v.confirm=$('confirm').value;v.port=+$('port').value;for(let k of ['photos','autostart','authorize'])v[k]=$(k).checked;return v}
async function next(){if(step<3){if(step===0&&(!$('name').value||!$('email').validity.valid||!$('email').value||$('password').value.length<12||$('password').value!==$('confirm').value)){error('Enter your name, valid email and matching passwords of at least 12 characters.');return}if(step===1&&['programs','data','files'].some(k=>!$(k).value)){error('Choose all three folders.');return}show(step+1);return}try{await api('install',request());busy=true;$('next').disabled=true;$('back').disabled=true;$('progress').hidden=false;$('error').hidden=true;for(let k of ['password','confirm','cfToken'])$(k).value='';poll()}catch(e){error(e)}}
async function browse(id){try{let r=await api('browse',{});if(r.path)$(id).value=r.path}catch(e){error(e)}}
function connection(){$('public').hidden=$('mode').value==='local';$('cloudflare').hidden=$('mode').value!=='cloudflare'}
async function poll(){try{let r=await api('state');$('version').textContent=r.version;$('phase').textContent=r.phase;if(r.error){busy=false;$('progress').hidden=true;error(r.error);$('back').disabled=false;$('next').disabled=false;return}if(r.ready){busy=false;installed=true;$('progress').hidden=true;$('navigation').hidden=true;$('complete').hidden=false;$('installTitle').textContent='Your workspace is ready.';$('workspaceLink').href=r.origin;return}if(r.busy)setTimeout(poll,1000)}catch(e){error(e)}}
async function launch(){try{await api('launch',{});$('launch').disabled=true;$('launch').textContent='Workspace is starting…'}catch(e){error(e)}}
poll();
</script></body></html>`
